    def handle(self, *args, **options):

        self.stdout.write(
            self.style.SUCCESS(
                "Career assessment import started..."
            )
        )


        # ---------------------------------------------------------
        # CREATE CAREERS, SKILLS AND CAREER-SKILL MAPPINGS
        # ---------------------------------------------------------

        for career_name, skill_rows in self.CAREER_SKILLS.items():

            career = CareerPath.objects.filter(
                name=career_name
            ).first()

            if not career:

                career = CareerPath.objects.create(
                    name=career_name,
                    description=f"Career path for {career_name} professionals."
                )

            for skill_name, required_level, priority, description in skill_rows:

                skill, created = Skill.objects.get_or_create(
                    name=skill_name,
                    defaults={
                        "description": description,
                        "is_active": True
                    }
                )

                if not skill.description:

                    skill.description = description

                    skill.save(
                        update_fields=["description"]
                    )

                career.skills.add(skill)

                CareerSkill.objects.update_or_create(
                    career_path=career,
                    skill=skill,
                    defaults={
                        "required_level": required_level,
                        "priority": priority,
                        "is_required": True
                    }
                )


        # ---------------------------------------------------------
        # ADD QUESTIONS
        # ---------------------------------------------------------

        for career_name, questions in self.QUESTIONS.items():

            career = CareerPath.objects.filter(
                name=career_name
            ).first()

            if not career:

                self.stdout.write(
                    self.style.ERROR(
                        f"Career '{career_name}' does not exist."
                    )
                )

                continue


            added_count = 0
            skipped_count = 0


            for data in questions:

                skill = Skill.objects.filter(
                    name=data["skill"]
                ).first()


                if not skill:

                    self.stdout.write(
                        self.style.ERROR(
                            f"Skill '{data['skill']}' does not exist."
                        )
                    )

                    continue


                # Avoid duplicate questions
                existing = AssessmentQuestion.objects.filter(
                    question=data["question"]
                ).first()


                if existing:

                    existing.option_a = data["option_a"]
                    existing.option_b = data["option_b"]
                    existing.option_c = data["option_c"]
                    existing.option_d = data["option_d"]
                    existing.correct_answer = data["correct_answer"]
                    existing.category = data["category"]
                    existing.difficulty = data["difficulty"]
                    existing.skill = skill

                    existing.save()

                    existing.career_paths.add(career)

                    skipped_count += 1

                    continue


                question = AssessmentQuestion.objects.create(

                    question=data["question"],

                    option_a=data["option_a"],

                    option_b=data["option_b"],

                    option_c=data["option_c"],

                    option_d=data["option_d"],

                    correct_answer=data["correct_answer"],

                    category=data["category"],

                    difficulty=data["difficulty"],

                    skill=skill,

                )


                question.career_paths.add(career)

                added_count += 1


            self.stdout.write(
                self.style.SUCCESS(
                    f"{career_name}: Added {added_count} | Existing/updated {skipped_count} | Total {len(questions)}"
                )
            )


        # ---------------------------------------------------------
        # FINAL MESSAGE
        # ---------------------------------------------------------

        self.stdout.write(
            self.style.SUCCESS(
                "=============================================="
            )
        )

        self.stdout.write(
            self.style.SUCCESS(
                "Career assessment import completed!"
            )
        )

        self.stdout.write(
            self.style.SUCCESS(
                "Data Scientist              -> 60 questions"
            )
        )

        self.stdout.write(
            self.style.SUCCESS(
                "Frontend Developer           -> 60 questions"
            )
        )

        self.stdout.write(
            self.style.SUCCESS(
                "Full Stack Developer         -> 60 questions"
            )
        )

        self.stdout.write(
            self.style.SUCCESS(
                "Java Developer              -> 60 questions"
            )
        )

        self.stdout.write(
            self.style.SUCCESS(
                "TOTAL                        -> 240 questions"
            )
        )

        self.stdout.write(
            self.style.SUCCESS(
                "=============================================="
            )
        )
